window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f691797e78f21ca4"]={"versions": [{"id": "FIG-f691797e78f21ca4", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm des erweiterten AUTOSAR-Kommunikationsstacks (AUTOSAR Classic Platform). Dargestellt ist die Einbettung des Socket-basierten Ethernet-Kommunikationspfads neben den klassischen Bus-Subsystemen (FlexRay, CAN, LIN) über vier Architekturschichten: Runtime Environment (RTE), Communication Services (BSW-Hauptschicht), Communication HW Abstraction und Communication Drivers. Hervorgehoben sind die ethernetbezogenen Komponenten (Socket adaptor inkl. DoIP, UDP NM Module, Ethernet Interface und Ethernet Driver) zur Illustration der Ethernet-Erweiterung im AUTOSAR-Basissoftware-Gesamtgefüge.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>RTE (Runtime Environment)</strong>: Oberste Schicht zur Signalkopplung mit den Software-Components.\n</li><li><strong>Communication Services</strong>:\n<ul class=\"fig-list\"><li><code>AUTOSAR COM</code>: Signal-zu-PDU-Umsetzung in Richtung <code>PDU Router</code> über <code>Signals</code> und <code>I-PDU</code>.\n</li><li><code>IPDU multiplexer</code>: Multiplexing von I-PDUs vor dem <code>PDU Router</code>.\n</li><li><code>DCM</code> (Diagnostic Communication Manager): Diagnosedienst-Abwicklung über <code>I-PDU</code>.\n</li><li><code>Communication Manager</code>: Übergreifendes Kommunikationsmanagement, steuert über Zustandsverbindungen (orange) <code>FlexRay State Manager</code>, <code>CAN State Manager</code>, <code>LIN State Manager</code> und <code>Eth State Manager</code>.\n</li><li><code>Generic NM interface</code> &amp; <code>NM Coordinator</code>: Netzwerkmanagement-Steuerung über <code>UDP NM Module</code> sowie busbezogene NM-Module.\n</li><li><code>PDU Router</code>: Zentrales PDU-Routing zwischen oberen Kommunikationsmodulen, <code>Socket adaptor</code>, Transportprotokollen (<code>FlexRay TP</code>, <code>CAN TP</code>) und Hardware-Abstraktionen.\n</li><li><code>Socket adaptor</code> (mit eingebettetem <code>DoIP</code>): Vermittlung zwischen PDU-basierter Kommunikation (<code>I-PDU</code>) und dem <code>Socket Interface</code>.\n</li><li><code>COTS TCP/IP Stack</code>: Enthält <code>Socket Interface</code>, Transportprotokolle <code>UDP</code> (Messages) und <code>TCP</code> (Streams), Netzwerkschicht <code>IP</code> (Packet, Segment), Hilfsprotokolle <code>DHCP</code>, <code>ARP</code> und <code>ICMP</code>.\n</li></ul>\n</li><li><strong>Communication HW Abstraction</strong>:\n<ul class=\"fig-list\"><li><code>Ethernet Interface</code>: Vermittelt zwischen <code>COTS TCP/IP Stack</code> (<code>Datagram</code>), <code>Eth State Manager</code> und <code>Ethernet Driver</code>.\n</li><li><code>FlexRay Interface</code>, <code>CAN Interface</code>, <code>LIN Interface (incl. LIN TP)</code>.\n</li></ul>\n</li><li><strong>Communication Drivers</strong>:\n<ul class=\"fig-list\"><li><code>Ethernet Driver</code>: Physische Frame-Übertragung (<code>Eth-Frame</code>).\n</li><li><code>FlexRay Driver</code>, <code>CAN Driver</code>, <code>LIN Low Level Driver</code>: Physische Übertragung von <code>L-PDU</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sendedatenfluss Ethernet / Socket Adaptor</strong>: Signale gelangen von der RTE über AUTOSAR COM als I-PDUs an den PDU Router. Der PDU Router leitet I-PDUs an den Socket adaptor weiter. Der Socket adaptor bedient das Socket Interface entweder über UDP-Messages oder TCP-Streams. Innerhalb des COTS TCP/IP Stacks werden Datenpakete/Segmente über IP zu Datagrams gebündelt und an das Ethernet Interface übergeben. Das Ethernet Interface steuert den Ethernet Driver zur Übertragung von Ethernet-Frames an.\n</li><li><strong>DoIP-Pfad</strong>: Diagnosedaten werden vom PDU Router direkt über den im Socket adaptor integrierten DoIP-Baustein auf Socket-Ebene transportiert.\n</li><li><strong>Klassische Buspfade</strong>: PDU Router tauscht I-PDUs mit IPDU multiplexer, DCM und COM aus; segmentierte N-PDUs fließen über CAN TP bzw. FlexRay TP zum CAN Interface bzw. FlexRay Interface, während LIN-PDUs direkt über das LIN Interface abgewickelt werden.\n</li><li><strong>Zustands- und NM-Ablauf</strong>: Der Communication Manager steuert die State Manager aller Busdomänen. Eth State Manager interagiert mit Ethernet Interface und UDP NM Module; UDP NM Module tauscht PDUs über das Socket Interface bzw. Ethernet Interface aus.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Bildet die funktionale Zuordnung und Schnittstellenkapselung von Ethernet in der AUTOSAR-Kommunikationsarchitektur ab.\n</li><li>Socket adaptor fungiert als Protokollbrücke, um PDU-basierte AUTOSAR-Konzepte an socketbasierte COTS-Netzwerkstacks anzubinden.\n</li><li>Klare Trennung zwischen PDU-Ebene (I-PDU, N-PDU, L-PDU) und Socket-/Netzwerkeinheiten (Messages, Streams, Packets, Segments, Datagrams, Eth-Frames).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f8fb6f7b92e19fe3", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm des erweiterten AUTOSAR-Kommunikationsstacks (AUTOSAR Classic Platform). Dargestellt ist die standardisierte Einbettung des Ethernet-Kommunikationspfads neben den klassischen Bus-Subsystemen (FlexRay, CAN, LIN) über vier Architekturschichten: Runtime Environment (RTE), Communication Services (BSW-Hauptschicht), Communication HW Abstraction und Communication Drivers. Der Ethernet-Zweig ist vollständig als AUTOSAR-Basissoftware mit integriertem AUTOSAR TCP/IP Stack, Socket Adaptor, DoIP, Service Discovery (Sd) und BSW Mode Manager (BswM) spezifiziert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>RTE (Runtime Environment)</strong>: Oberste Schicht zur Signalkopplung mit Applikation und BSW; interagiert über Signale mit <code>AUTOSAR COM</code> und über Steuerverbindungen mit <code>BswM</code>.\n</li><li><strong>Communication Services</strong>:\n<ul class=\"fig-list\"><li><code>BswM</code> (BSW Mode Manager): Modemanagement für Basissoftware-Module; interagiert mit der RTE und steuert <code>Sd</code>.\n</li><li><code>AUTOSAR COM</code>, <code>IPDU multiplexer</code>, <code>DCM</code>: Signale und I-PDUs in Richtung <code>PDU Router</code>.\n</li><li><code>Communication Manager</code>: Koordination von <code>FlexRay State Manager</code>, <code>CAN State Manager</code>, <code>LIN State Manager</code> und <code>Eth State Manager</code>.\n</li><li><code>Generic NM interface</code> &amp; <code>NM Coordinator</code>: NM-Koordination mit <code>UDP NM Module</code> und Busschnittstellen.\n</li><li><code>PDU Router</code>: Verteilt I-PDUs zwischen oberen Modulen, <code>DoIP</code>, <code>Sd</code>, <code>Socket Adaptor</code>, <code>FlexRay TP</code> und <code>CAN TP</code>.\n</li><li><code>Sd</code> (Service Discovery): Autonomes Modul zur Dienstsuche und Verbindungssteuerung, gekoppelt mit <code>BswM</code> und über <code>I-PDU</code> mit <code>Socket Adaptor</code>.\n</li><li><code>DoIP</code> (Diagnostics over IP): Eigenständiges BSW-Modul zwischen <code>PDU Router</code> (I-PDU) und <code>Socket Adaptor</code> (I-PDU).\n</li><li><code>Socket Adaptor</code>: Zentrale Schnittstelle zwischen I-PDU-Verkehr (<code>PDU Router</code>, <code>DoIP</code>, <code>Sd</code>) und dem <code>AUTOSAR TCP/IP Stack</code>.\n</li><li><code>AUTOSAR TCP/IP Stack</code>: Enthält Transportprotokolle <code>UDP</code> (Messages) und <code>TCP</code> (Streams), Netzwerkschicht <code>IPv4/v6</code> (Packet, Segment), <code>ARP/NDP</code>, <code>DHCP</code> und <code>ICMP</code>.\n</li></ul>\n</li><li><strong>Communication HW Abstraction</strong>:\n<ul class=\"fig-list\"><li><code>Ethernet Interface</code>: Kopplung mit <code>AUTOSAR TCP/IP Stack</code> (<code>Datagram</code>), <code>Eth State Manager</code> und <code>Ethernet Driver</code>.\n</li><li><code>FlexRay Interface</code>, <code>CAN Interface</code>, <code>LIN Interface (incl. LIN TP)</code>.\n</li></ul>\n</li><li><strong>Communication Drivers</strong>:\n<ul class=\"fig-list\"><li><code>Ethernet Driver</code>: Physische Frame-Übertragung (<code>Eth-Frame</code>).\n</li><li><code>FlexRay Driver</code>, <code>CAN Driver</code>, <code>LIN Low Level Driver</code>: Physische Übertragung von <code>L-PDU</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sendedatenfluss Ethernet / Socket Adaptor</strong>: I-PDUs gelangen vom PDU Router, von Sd oder von DoIP an den Socket Adaptor. Der Socket Adaptor interagiert direkt mit dem AUTOSAR TCP/IP Stack über UDP-Messages oder TCP-Streams. IPv4/v6 verarbeitet Segmente/Packets und übergibt Datagrams an das Ethernet Interface, welches Frames an den Ethernet Driver weiterleitet.\n</li><li><strong>Service Discovery &amp; Diagnosedienst</strong>: Sd wickelt Service-Discovery-Nachrichten als I-PDUs über den Socket Adaptor ab und wird vom BswM gesteuert. DoIP wickelt Diagnosedaten als I-PDUs zwischen PDU Router und Socket Adaptor ab.\n</li><li><strong>Klassische Buspfade</strong>: Transport- und Datenpfade über FlexRay TP, CAN TP und die Interfaces (FlexRay, CAN, LIN) zu den jeweiligen Treibern.\n</li><li><strong>Zustandssteuerung</strong>: Eth State Manager steuert sowohl das Ethernet Interface als auch den AUTOSAR TCP/IP Stack über dedizierte Zustandsverbindungen (orange).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Standardisierter AUTOSAR-Ethernet-Stack: Ersetzt proprietäre COTS-Lösungen durch einen normierten AUTOSAR TCP/IP Stack mit dualem Stack (IPv4/IPv6) und Adressauflösung via ARP und NDP.\n</li><li>Klare funktionale Kapselung: DoIP und Sd sind als eigenständige BSW-Komponenten oberhalb des Socket Adaptor standardisiert.\n</li><li>Zustandsverwaltung: Der Eth State Manager wirkt direkt auf Netzwerk- und Schnittstellenebene (Ethernet Interface und AUTOSAR TCP/IP Stack).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-dd10248c7886c451", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm des erweiterten AUTOSAR-Kommunikationsstacks (AUTOSAR Classic Platform). Dargestellt ist die standardisierte Einbettung des Ethernet-Kommunikationspfads neben den klassischen Bus-Subsystemen (FlexRay, CAN, LIN) über vier Architekturschichten: Runtime Environment (RTE), Communication Services (BSW-Hauptschicht), Communication HW Abstraction und Communication Drivers. Der Ethernet-Zweig ist vollständig als AUTOSAR-Basissoftware mit integriertem AUTOSAR TCP/IP Stack, Socket Adaptor, DoIP, Service Discovery (Sd) und BSW Mode Manager (BswM) spezifiziert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>RTE (Runtime Environment)</strong>: Oberste Schicht zur Signalkopplung mit Applikation und BSW; interagiert über Signale mit <code>AUTOSAR COM</code> und über Steuerverbindungen mit <code>BswM</code>.\n</li><li><strong>Communication Services</strong>:\n<ul class=\"fig-list\"><li><code>BswM</code> (BSW Mode Manager): Modemanagement für Basissoftware-Module; interagiert mit der RTE und steuert <code>Sd</code>.\n</li><li><code>AUTOSAR COM</code>, <code>IPDU multiplexer</code>, <code>DCM</code>: Signale und I-PDUs in Richtung <code>PDU Router</code>.\n</li><li><code>Communication Manager</code>: Koordination von <code>FlexRay State Manager</code>, <code>CAN State Manager</code>, <code>LIN State Manager</code> und <code>Eth State Manager</code>.\n</li><li><code>Generic NM interface</code> &amp; <code>NM Coordinator</code>: NM-Koordination mit <code>UDP NM Module</code> und Busschnittstellen.\n</li><li><code>PDU Router</code>: Verteilt I-PDUs zwischen oberen Modulen, <code>DoIP</code>, <code>Sd</code>, <code>Socket Adaptor</code>, <code>FlexRay TP</code> und <code>CAN TP</code>.\n</li><li><code>Sd</code> (Service Discovery): Autonomes Modul zur Dienstsuche und Verbindungssteuerung, gekoppelt mit <code>BswM</code> und über <code>I-PDU</code> mit <code>Socket Adaptor</code>.\n</li><li><code>DoIP</code> (Diagnostics over IP): Eigenständiges BSW-Modul zwischen <code>PDU Router</code> (I-PDU) und <code>Socket Adaptor</code> (I-PDU).\n</li><li><code>Socket Adaptor</code>: Zentrale Schnittstelle zwischen I-PDU-Verkehr (<code>PDU Router</code>, <code>DoIP</code>, <code>Sd</code>) und dem <code>AUTOSAR TCP/IP Stack</code>.\n</li><li><code>AUTOSAR TCP/IP Stack</code>: Enthält Transportprotokolle <code>UDP</code> (Messages) und <code>TCP</code> (Streams), Netzwerkschicht <code>IPv4/v6</code> (Packet, Segment), <code>ARP/NDP</code>, <code>DHCP</code> und <code>ICMP</code>.\n</li></ul>\n</li><li><strong>Communication HW Abstraction</strong>:\n<ul class=\"fig-list\"><li><code>Ethernet Interface</code>: Kopplung mit <code>AUTOSAR TCP/IP Stack</code> (<code>Datagram</code>), <code>Eth State Manager</code> und <code>Ethernet Driver</code>.\n</li><li><code>FlexRay Interface</code>, <code>CAN Interface</code>, <code>LIN Interface (incl. LIN TP)</code>.\n</li></ul>\n</li><li><strong>Communication Drivers</strong>:\n<ul class=\"fig-list\"><li><code>Ethernet Driver</code>: Physische Frame-Übertragung (<code>Eth-Frame</code>).\n</li><li><code>FlexRay Driver</code>, <code>CAN Driver</code>, <code>LIN Low Level Driver</code>: Physische Übertragung von <code>L-PDU</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sendedatenfluss Ethernet / Socket Adaptor</strong>: I-PDUs gelangen vom PDU Router, von Sd oder von DoIP an den Socket Adaptor. Der Socket Adaptor interagiert direkt mit dem AUTOSAR TCP/IP Stack über UDP-Messages oder TCP-Streams. IPv4/v6 verarbeitet Segmente/Packets und übergibt Datagrams an das Ethernet Interface, welches Frames an den Ethernet Driver weiterleitet.\n</li><li><strong>Service Discovery &amp; Diagnosedienst</strong>: Sd wickelt Service-Discovery-Nachrichten als I-PDUs über den Socket Adaptor ab und wird vom BswM gesteuert. DoIP wickelt Diagnosedaten als I-PDUs zwischen PDU Router und Socket Adaptor ab.\n</li><li><strong>Klassische Buspfade</strong>: Transport- und Datenpfade über FlexRay TP, CAN TP und die Interfaces (FlexRay, CAN, LIN) zu den jeweiligen Treibern.\n</li><li><strong>Zustandssteuerung</strong>: Eth State Manager steuert sowohl das Ethernet Interface als auch den AUTOSAR TCP/IP Stack über dedizierte Zustandsverbindungen (orange).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Standardisierter AUTOSAR-Ethernet-Stack: Ersetzt proprietäre COTS-Lösungen durch einen normierten AUTOSAR TCP/IP Stack mit dualem Stack (IPv4/IPv6) und Adressauflösung via ARP und NDP.\n</li><li>Klare funktionale Kapselung: DoIP und Sd sind als eigenständige BSW-Komponenten oberhalb des Socket Adaptor standardisiert.\n</li><li>Zustandsverwaltung: Der Eth State Manager wirkt direkt auf Netzwerk- und Schnittstellenebene (Ethernet Interface und AUTOSAR TCP/IP Stack).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ff0b2a00d8778347", "releases": ["R21-11", "R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm des erweiterten AUTOSAR-Kommunikationsstacks (AUTOSAR Classic Platform). Dargestellt ist die standardisierte Einbettung des Ethernet-Kommunikationspfads neben den klassischen Bus-Subsystemen (FlexRay, CAN, LIN) über vier Architekturschichten: Runtime Environment (RTE), Communication Services (BSW-Hauptschicht), Communication HW Abstraction und Communication Drivers. Der Ethernet-Zweig ist vollständig als AUTOSAR-Basissoftware mit integriertem AUTOSAR TCP/IP Stack, Socket Adaptor, DoIP, Service Discovery (Sd) und BSW Mode Manager (BswM) spezifiziert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>RTE (Runtime Environment)</strong>: Oberste Schicht zur Signalkopplung mit Applikation und BSW; interagiert über Signale mit <code>AUTOSAR COM</code> und über Steuerverbindungen mit <code>BswM</code>.\n</li><li><strong>Communication Services</strong>:\n<ul class=\"fig-list\"><li><code>BswM</code> (BSW Mode Manager): Modemanagement für Basissoftware-Module; interagiert mit der RTE und steuert <code>Sd</code>.\n</li><li><code>AUTOSAR COM</code>, <code>IPDU multiplexer</code>, <code>DCM</code>: Signale und I-PDUs in Richtung <code>PDU Router</code>.\n</li><li><code>Communication Manager</code>: Koordination von <code>FlexRay State Manager</code>, <code>CAN State Manager</code>, <code>LIN State Manager</code> und <code>Eth State Manager</code>.\n</li><li><code>Generic NM interface</code> &amp; <code>NM Coordinator</code>: NM-Koordination mit <code>UDP NM Module</code> und Busschnittstellen.\n</li><li><code>PDU Router</code>: Verteilt I-PDUs zwischen oberen Modulen, <code>DoIP</code>, <code>Sd</code>, <code>Socket Adaptor</code>, <code>FlexRay TP</code> und <code>CAN TP</code>.\n</li><li><code>Sd</code> (Service Discovery): Autonomes Modul zur Dienstsuche und Verbindungssteuerung, gekoppelt mit <code>BswM</code> und über <code>I-PDU</code> mit <code>Socket Adaptor</code>.\n</li><li><code>DoIP</code> (Diagnostics over IP): Eigenständiges BSW-Modul zwischen <code>PDU Router</code> (I-PDU) und <code>Socket Adaptor</code> (I-PDU).\n</li><li><code>Socket Adaptor</code>: Zentrale Schnittstelle zwischen I-PDU-Verkehr (<code>PDU Router</code>, <code>DoIP</code>, <code>Sd</code>) und dem <code>AUTOSAR TCP/IP Stack</code>.\n</li><li><code>AUTOSAR TCP/IP Stack</code>: Enthält Transportprotokolle <code>UDP</code> (Messages) und <code>TCP</code> (Streams), Netzwerkschicht <code>IPv4/v6</code> (Packet, Segment), <code>ARP/NDP</code>, <code>DHCP</code> und <code>ICMP</code>.\n</li></ul>\n</li><li><strong>Communication HW Abstraction</strong>:\n<ul class=\"fig-list\"><li><code>Ethernet Interface</code>: Kopplung mit <code>AUTOSAR TCP/IP Stack</code> (<code>Datagram</code>), <code>Eth State Manager</code> und <code>Ethernet Driver</code>.\n</li><li><code>FlexRay Interface</code>, <code>CAN Interface</code>, <code>LIN Interface (incl. LIN TP)</code>.\n</li></ul>\n</li><li><strong>Communication Drivers</strong>:\n<ul class=\"fig-list\"><li><code>Ethernet Driver</code>: Physische Frame-Übertragung (<code>Eth-Frame</code>).\n</li><li><code>FlexRay Driver</code>, <code>CAN Driver</code>, <code>LIN Low Level Driver</code>: Physische Übertragung von <code>L-PDU</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sendedatenfluss Ethernet / Socket Adaptor</strong>: I-PDUs gelangen vom PDU Router, von Sd oder von DoIP an den Socket Adaptor. Der Socket Adaptor interagiert direkt mit dem AUTOSAR TCP/IP Stack über UDP-Messages oder TCP-Streams. IPv4/v6 verarbeitet Segmente/Packets und übergibt Datagrams an das Ethernet Interface, welches Frames an den Ethernet Driver weiterleitet.\n</li><li><strong>Service Discovery &amp; Diagnosedienst</strong>: Sd wickelt Service-Discovery-Nachrichten als I-PDUs über den Socket Adaptor ab und wird vom BswM gesteuert. DoIP wickelt Diagnosedaten als I-PDUs zwischen PDU Router und Socket Adaptor ab.\n</li><li><strong>Klassische Buspfade</strong>: Transport- und Datenpfade über FlexRay TP, CAN TP und die Interfaces (FlexRay, CAN, LIN) zu den jeweiligen Treibern.\n</li><li><strong>Zustandssteuerung</strong>: Eth State Manager steuert sowohl das Ethernet Interface als auch den AUTOSAR TCP/IP Stack über dedizierte Zustandsverbindungen (orange).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Standardisierter AUTOSAR-Ethernet-Stack: Ersetzt proprietäre COTS-Lösungen durch einen normierten AUTOSAR TCP/IP Stack mit dualem Stack (IPv4/IPv6) und Adressauflösung via ARP und NDP.\n</li><li>Klare funktionale Kapselung: DoIP und Sd sind als eigenständige BSW-Komponenten oberhalb des Socket Adaptor standardisiert.\n</li><li>Zustandsverwaltung: Der Eth State Manager wirkt direkt auf Netzwerk- und Schnittstellenebene (Ethernet Interface und AUTOSAR TCP/IP Stack).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f691797e78f21ca4", "to": "FIG-f8fb6f7b92e19fe3", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Socket Adaptor / TCP/IP Stack: Rote Hervorhebungsumrandungen (an Socket adaptor / DoIP, UDP NM Module, Ethernet Interface, Ethernet Driver) entfernt.\n</li><li>COTS TCP/IP Stack ersetzt durch AUTOSAR TCP/IP Stack; Protokollkomponente IP ersetzt durch IPv4/v6; ARP ergänzt um NDP (ARP/NDP); generisches Socket Interface durch direkte Anbindung des Socket Adaptor an AUTOSAR TCP/IP Stack ersetzt.\n</li><li>Neuer BSW-Baustein Sd (Service Discovery) zwischen BswM (BswM neu an RTE angebunden) und Socket Adaptor eingefügt, mit I-PDU-Verbindung zu Socket Adaptor.\n</li><li>DoIP als eigenständiger Baustein neben Sd über Socket Adaptor und unterhalb PDU Router platziert (zuvor innerhalb des Socket adaptor eingezeichnet).\n</li><li>Neue bidirektionale Steuerungs-/Zustandsverbindung (orange) zwischen Eth State Manager und AUTOSAR TCP/IP Stack ergänzt.\n</li></ul>"}, {"from": "FIG-f8fb6f7b92e19fe3", "to": "FIG-dd10248c7886c451", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-dd10248c7886c451", "to": "FIG-ff0b2a00d8778347", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
